314	@@ -0,0 +1,65 @@
315	+using Microsoft.AspNetCore.Mvc;
316	+using seed_b_backend.Api.Application;
317	+using seed_b_backend.Api.Controllers.Dtos;
318	+
319	+namespace seed_b_backend.Api.Controllers;
320	+
321	+[ApiController]
322	+[Route("api/orders")]
323	+public class OrdersController(OrderService orderService) : ControllerBase
324	+{
325	+    [HttpPost]
326	+    public async Task<ActionResult<OrderDto>> PlaceOrder(
327	+        [FromHeader(Name = "X-Cart-Id")] string? cartId,
328	+        [FromBody] PlaceOrderRequest request,
329	+        CancellationToken ct = default)
330	+    {
331	+        var parsedCartId = Guid.TryParse(cartId, out var parsed) ? parsed : (Guid?)null;
332	+
333	+        var result = await orderService.PlaceOrderAsync(
334	+            parsedCartId, request.CustomerName, request.DeliveryAddress, request.Email, ct);
335	+
336	+        return result.Status switch
337	+        {
338	+            OrderPlacementStatus.CartEmpty => Conflict(new OrderRejectionDto
339	+            {
340	+                Error = "Warenkorb ist leer",
341	+                Lines = []
342	+            }),
343	+            OrderPlacementStatus.LinesRejected => Conflict(new OrderRejectionDto
344	+            {
345	+                Error = "Bestellung abgelehnt",
346	+                Lines = result.RejectedLines!
347	+                    .Select(l => new OrderRejectionLineDto
348	+                    {
349	+                        ProductId = l.ProductId,
350	+                        SupplierId = l.SupplierId,
351	+                        Reason = l.Reason == OrderLineRejectionReason.InvalidQuantity
352	+                            ? "unzulaessige_menge"
353	+                            : "angebot_nicht_mehr_verfuegbar"
354	+                    })
355	+                    .ToList()
356	+            }),
357	+            _ => StatusCode(StatusCodes.Status201Created, MapToDto(result.Order!))
358	+        };
359	+    }
360	+
361	+    private static OrderDto MapToDto(OrderResult result) => new()
362	+    {
363	+        OrderId = result.OrderId,
364	+        Status = result.Status,
365	+        TotalPrice = result.TotalPrice,
366	+        Items = result.Items
367	+            .Select(l => new OrderItemDto
368	+            {
369	+                ProductId = l.ProductId,
370	+                ProductName = l.ProductName,
371	+                SupplierId = l.SupplierId,
372	+                SupplierName = l.SupplierName,
373	+                Quantity = l.Quantity,
374	+                UnitPrice = l.UnitPrice,
375	+                LineTotal = l.UnitPrice * l.Quantity
376	+            })
377	+            .ToList()
378	+    };
379	+}
