94	+using System.Data;
95	+using Microsoft.EntityFrameworkCore;
96	+using seed_b_backend.Api.Data;
97	+using seed_b_backend.Api.Domain;
98	+
99	+namespace seed_b_backend.Api.Application;
100	+
101	+public class OrderService(AppDbContext context)
102	+{
103	+    public async Task<OrderPlacementResult> PlaceOrderAsync(
104	+        Guid? cartId,
105	+        string customerName,
106	+        string deliveryAddress,
107	+        string email,
108	+        CancellationToken ct = default)
109	+    {
110	+        if (cartId is null)
111	+        {
112	+            return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
113	+        }
114	+
115	+        var lines = await context.CartItems
116	+            .Where(ci => ci.CartId == cartId)
117	+            .Select(ci => new { ci.ProductId, ci.SupplierId, ci.Quantity })
118	+            .ToListAsync(ct);
119	+
120	+        if (lines.Count == 0)
121	+        {
122	+            return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
123	+        }
124	+
125	+        var invalidQuantityLines = lines
126	+            .Where(l => l.Quantity < 1)
127	+            .Select(l => new OrderLineRejection
128	+            {
129	+                ProductId = l.ProductId,
130	+                SupplierId = l.SupplierId,
131	+                Reason = OrderLineRejectionReason.InvalidQuantity
132	+            })
133	+            .ToList();
134	+        if (invalidQuantityLines.Count > 0)
135	+        {
136	+            return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = invalidQuantityLines };
137	+        }
138	+
139	+        await using var transaction = await context.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct);
140	+
141	+        var offerPrices = new Dictionary<(string ProductId, string SupplierId), decimal>();
142	+        var offerGoneLines = new List<OrderLineRejection>();
143	+        foreach (var line in lines)
144	+        {
145	+            var price = await context.Offers
146	+                .Where(o => o.ProductId == line.ProductId && o.SupplierId == line.SupplierId)
147	+                .Select(o => (decimal?)o.Price)
148	+                .SingleOrDefaultAsync(ct);
149	+
150	+            if (price is null)
151	+            {
152	+                offerGoneLines.Add(new OrderLineRejection
153	+                {
154	+                    ProductId = line.ProductId,
155	+                    SupplierId = line.SupplierId,
156	+                    Reason = OrderLineRejectionReason.OfferGone
157	+                });
158	+            }
159	+            else
160	+            {
161	+                offerPrices[(line.ProductId, line.SupplierId)] = price.Value;
162	+            }
163	+        }
164	+
165	+        if (offerGoneLines.Count > 0)
166	+        {
167	+            await transaction.RollbackAsync(ct);
168	+            return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = offerGoneLines };
169	+        }
170	+
171	+        var order = new Order
172	+        {
173	+            Id = Guid.NewGuid(),
174	+            CustomerName = customerName,
175	+            DeliveryAddress = deliveryAddress,
176	+            Email = email
177	+        };
178	+        context.Orders.Add(order);
179	+
180	+        foreach (var line in lines)
181	+        {
182	+            context.OrderItems.Add(new OrderItem
183	+            {
184	+                OrderId = order.Id,
185	+                ProductId = line.ProductId,
186	+                SupplierId = line.SupplierId,
187	+                Quantity = line.Quantity,
188	+                UnitPrice = offerPrices[(line.ProductId, line.SupplierId)]
189	+            });
190	+        }
191	+
192	+        await context.SaveChangesAsync(ct);
193	+        await context.CartItems.Where(ci => ci.CartId == cartId).ExecuteDeleteAsync(ct);
194	+        await transaction.CommitAsync(ct);
195	+
196	+        return new OrderPlacementResult
197	+        {
198	+            Status = OrderPlacementStatus.Success,
199	+            Order = await BuildOrderResultAsync(order.Id, ct)
200	+        };
201	+    }
202	+
203	+    private async Task<OrderResult> BuildOrderResultAsync(Guid orderId, CancellationToken ct)
204	+    {
205	+        var order = await context.Orders.SingleAsync(o => o.Id == orderId, ct);
206	+        var lines = await context.OrderItems
207	+            .Where(oi => oi.OrderId == orderId)
208	+            .Select(oi => new OrderResultLine
209	+            {
210	+                ProductId = oi.ProductId,
211	+                ProductName = oi.Product!.Name,
212	+                SupplierId = oi.SupplierId,
213	+                SupplierName = oi.Supplier!.Name,
214	+                Quantity = oi.Quantity,
215	+                UnitPrice = oi.UnitPrice
216	+            })
217	+            .ToListAsync(ct);
218	+
219	+        return new OrderResult
220	+        {
221	+            OrderId = order.Id,
222	+            Status = order.Status,
223	+            Items = lines,
224	+            TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
225	+        };
226	+    }
227	+}
