1174	+    [Fact]
1175	+    public async Task PlaceOrderAsync_ValidCart_CreatesOrderWithSnapshotPriceStatusNeuAndClearsCart()
1176	+    {
1177	+        var result = await _service.PlaceOrderAsync(_cartId, "Mara Muster", "Musterstraße 1, 12345 Musterstadt", "mara@example.com");
1178	+
