1180	+        Assert.Equal("Neu", result.Order!.Status);
1181	+        Assert.Single(result.Order.Items);
1182	+        Assert.Equal(10.00m, result.Order.Items[0].UnitPrice);
1183	+        Assert.Equal(2, result.Order.Items[0].Quantity);
1184	+        Assert.Equal(20.00m, result.Order.TotalPrice);
1185	+        Assert.Equal(0, await _context.CartItems.CountAsync(ci => ci.CartId == _cartId));
