1560	+import { HttpErrorResponse } from '@angular/common/http';
1561	+import { Component, inject, signal } from '@angular/core';
1562	+
1563	+import { CartApiService } from '../../cart/cart-api.service';
1564	+import { Cart } from '../../cart/cart.model';
1565	+import { CartService } from '../../../core/cart.service';
1566	+import { OrderApiService } from '../order-api.service';
1567	+import { Order, OrderRejection } from '../order.model';
1568	+
1569	+const REASON_TEXT: Record<string, string> = {
1570	+  unzulaessige_menge: 'unzulässige Menge',
1571	+  angebot_nicht_mehr_verfuegbar: 'Angebot nicht mehr verfügbar'
1572	+};
1573	+
1574	+@Component({
1575	+  selector: 'app-checkout-view',
1576	+  templateUrl: './checkout-view.html'
1577	+})
1578	+export class CheckoutView {
1579	+  private cartApi = inject(CartApiService);
1580	+  private orderApi = inject(OrderApiService);
1581	+  private cartService = inject(CartService);
1582	+
1583	+  protected readonly cart = signal<Cart | null>(null);
1584	+  protected readonly loading = signal(true);
1585	+  protected readonly loadError = signal<string | null>(null);
1586	+
1587	+  protected readonly customerName = signal('');
1588	+  protected readonly deliveryAddress = signal('');
1589	+  protected readonly email = signal('');
1590	+  protected readonly submitting = signal(false);
1591	+  protected readonly submitError = signal<string | null>(null);
1592	+  protected readonly rejectionLines = signal<string[]>([]);
1593	+  protected readonly placedOrder = signal<Order | null>(null);
1594	+
1595	+  constructor() {
1596	+    this.cartApi.getCart(this.cartService.cartId()).subscribe({
1597	+      next: (cart) => {
1598	+        this.cart.set(cart);
1599	+        this.loading.set(false);
1600	+      },
1601	+      error: () => {
1602	+        this.loading.set(false);
1603	+        this.loadError.set('Warenkorb konnte nicht geladen werden.');
1604	+      }
1605	+    });
1606	+  }
1607	+
1608	+  private describeLine(productId: string, supplierId: string): string {
1609	+    const item = this.cart()?.items.find((i) => i.productId === productId && i.supplierId === supplierId);
1610	+    return item ? `${item.productName} (${item.supplierName})` : `${productId}/${supplierId}`;
1611	+  }
1612	+
1613	+  protected placeOrder(): void {
1614	+    if (this.submitting()) {
1615	+      return;
1616	+    }
1617	+
1618	+    const cartId = this.cartService.cartId();
1619	+    const name = this.customerName().trim();
1620	+    const address = this.deliveryAddress().trim();
1621	+    const mail = this.email().trim();
1622	+    if (!cartId || !name || !address || !mail) {
1623	+      this.submitError.set('Bitte Name, Lieferadresse und E-Mail-Adresse angeben.');
1624	+      return;
1625	+    }
1626	+
1627	+    this.submitting.set(true);
1628	+    this.submitError.set(null);
1629	+    this.rejectionLines.set([]);
1630	+
1631	+    this.orderApi.placeOrder(cartId, name, address, mail).subscribe({
1632	+      next: (order) => {
1633	+        this.submitting.set(false);
1634	+        this.placedOrder.set(order);
1635	+      },
1636	+      error: (err: HttpErrorResponse) => {
1637	+        this.submitting.set(false);
1638	+        if (err.status === 409) {
1639	+          const rejection = err.error as OrderRejection;
1640	+          this.submitError.set(rejection.error);
1641	+          this.rejectionLines.set(
1642	+            rejection.lines.map(
1643	+              (l) => `${this.describeLine(l.productId, l.supplierId)}: ${REASON_TEXT[l.reason] ?? l.reason}`
1644	+            )
1645	+          );
1646	+        } else {
1647	+          this.submitError.set('Bestellung konnte nicht angelegt werden. Bitte Eingaben prüfen.');
1648	+        }
1649	+      }
1650	+    });
1651	+  }
1652	+}
