1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Domain;
4	
5	namespace seed_b_backend.Api.Application;
6	
7	public class CartService(AppDbContext context)
8	{
9	    public async Task<CartResult?> AddItemAsync(
10	        Guid? cartId,
11	        string productId,
12	        string supplierId,
13	        int quantity,
14	        CancellationToken ct = default)
15	    {
16	        var offerExists = await context.Offers
17	            .AnyAsync(o => o.ProductId == productId && o.SupplierId == supplierId, ct);
18	        if (!offerExists)
19	        {
20	            return null;
21	        }
22	
23	        var resolvedCartId = cartId is not null && await context.Carts.AnyAsync(c => c.Id == cartId, ct)
24	            ? cartId.Value
25	            : await CreateCartAsync(ct);
26	
27	        var updatedRows = await context.CartItems
28	            .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
29	            .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);
30	
31	        if (updatedRows == 0)
32	        {
33	            var newItem = new CartItem { CartId = resolvedCartId, ProductId = productId, SupplierId = supplierId, Quantity = quantity };
34	            context.CartItems.Add(newItem);
35	            try
36	            {
37	                await context.SaveChangesAsync(ct);
38	            }
39	            catch (DbUpdateException)
40	            {
41	                // Ein gleichzeitiges Hinzufügen desselben Produkt-Lieferant-Paars zu
42	                // diesem Warenkorb hat seine Zeile zwischen unserem ExecuteUpdateAsync
43	                // (traf nichts) und diesem Add eingefügt — der DB-Unique-Constraint
44	                // (zusammengesetzter Primärschlüssel, AD-1) lehnt unseren Insert ab,
45	                // statt still zu duplizieren. Fallback: Update, das jetzt garantiert
46	                // genau diese Zeile trifft. Identisches Muster wie RatingService
47	                // (Story 2.3) für den AD-5-Race.
48	                context.Entry(newItem).State = EntityState.Detached;
49	                var raceFallbackRows = await context.CartItems
50	                    .Where(ci => ci.CartId == resolvedCartId && ci.ProductId == productId && ci.SupplierId == supplierId)
51	                    .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, ci => ci.Quantity + quantity), ct);
52	
53	                if (raceFallbackRows == 0)
54	                {
55	                    throw;
56	                }
57	            }
58	        }
59	
60	        return await BuildCartResultAsync(resolvedCartId, ct);
61	    }
62	
63	    private async Task<Guid> CreateCartAsync(CancellationToken ct)
64	    {
65	        var cart = new Cart { Id = Guid.NewGuid() };
66	        context.Carts.Add(cart);
67	        await context.SaveChangesAsync(ct);
68	        return cart.Id;
69	    }
70	
71	    private async Task<CartResult> BuildCartResultAsync(Guid cartId, CancellationToken ct)
72	    {
73	        var lines = await context.CartItems
74	            .Where(ci => ci.CartId == cartId)
75	            .Join(context.Offers,
76	                ci => new { ci.ProductId, ci.SupplierId },
77	                o => new { o.ProductId, o.SupplierId },
78	                (ci, o) => new CartResultLine
79	                {
80	                    ProductId = ci.ProductId,
81	                    ProductName = o.Product!.Name,
82	                    SupplierId = ci.SupplierId,
83	                    SupplierName = o.Supplier!.Name,
84	                    Quantity = ci.Quantity,
85	                    UnitPrice = o.Price
86	                })
87	            .ToListAsync(ct);
88	
89	        return new CartResult
90	        {
91	            CartId = cartId,
92	            Items = lines,
93	            TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
94	        };
95	    }
96	
97	    public async Task<CartResult> GetCartAsync(Guid? cartId, CancellationToken ct = default)
98	    {
99	        if (cartId is null || !await context.Carts.AnyAsync(c => c.Id == cartId, ct))
100	        {
101	            return new CartResult { CartId = null, Items = [], TotalPrice = 0 };
102	        }
103	
104	        return await BuildCartResultAsync(cartId.Value, ct);
105	    }
106	
107	    public async Task<CartMutationResult> UpdateItemQuantityAsync(
108	        Guid cartId,
109	        string productId,
110	        string supplierId,
111	        int quantity,
112	        CancellationToken ct = default)
113	    {
114	        var itemExists = await context.CartItems
115	            .AnyAsync(ci => ci.CartId == cartId && ci.ProductId == productId && ci.SupplierId == supplierId, ct);
116	        if (!itemExists)
117	        {
118	            return new CartMutationResult { Status = CartMutationStatus.ItemNotFound };
119	        }
120	
121	        var offerExists = await context.Offers
122	            .AnyAsync(o => o.ProductId == productId && o.SupplierId == supplierId, ct);
123	        if (!offerExists)
124	        {
125	            return new CartMutationResult { Status = CartMutationStatus.OfferGone };
126	        }
127	
128	        await context.CartItems
129	            .Where(ci => ci.CartId == cartId && ci.ProductId == productId && ci.SupplierId == supplierId)
130	            .ExecuteUpdateAsync(s => s.SetProperty(ci => ci.Quantity, quantity), ct);
131	
132	        return new CartMutationResult
133	        {
134	            Status = CartMutationStatus.Success,
135	            Cart = await BuildCartResultAsync(cartId, ct)
136	        };
137	    }
138	
139	    public async Task<CartResult> RemoveItemAsync(
140	        Guid? cartId,
141	        string productId,
142	        string supplierId,
143	        CancellationToken ct = default)
144	    {
145	        if (cartId is null || !await context.Carts.AnyAsync(c => c.Id == cartId, ct))
146	        {
147	            return new CartResult { CartId = null, Items = [], TotalPrice = 0 };
148	        }
149	
150	        await context.CartItems
151	            .Where(ci => ci.CartId == cartId && ci.ProductId == productId && ci.SupplierId == supplierId)
152	            .ExecuteDeleteAsync(ct);
153	
154	        return await BuildCartResultAsync(cartId.Value, ct);
155	    }
156	}
